FLootRow URecordTrimLibrary::GetLootRow(int32 Key, bool& bFound)
{
    const FLootRow* Found = FRecordTrim::Loot().FindByIndex(Key);

    bFound = Found != nullptr;

    // A copy, because Blueprint takes a struct by value and the row belongs to the table.
    // A default one when the key is not there, which is why bFound is not decoration.
    return Found != nullptr ? *Found : FLootRow();
}

int32 URecordTrimLibrary::GetLootRowCount()
{
    return FRecordTrim::Loot().Records().Num();
}

FLootRow URecordTrimLibrary::GetLootRowAt(int32 Position, bool& bFound)
{
    const TArray<FLootRow>& Rows = FRecordTrim::Loot().Records();

    bFound = Rows.IsValidIndex(Position);

    return bFound ? Rows[Position] : FLootRow();
}


